import pathlib,json,hashlib,subprocess,datetime
R=pathlib.Path(__file__).parent;S=R/'source';SRC=R.parent/'coding-any-repair-20261014';E=R.parent/'coding-any-repair-20261014-evidence'
def sha(p):return hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
def read(p):return json.loads(pathlib.Path(p).read_text(encoding='utf-8-sig'))
def save(n,o):(R/n).write_text(json.dumps(o,ensure_ascii=False,indent=2),encoding='utf8')
def git(*a):return subprocess.check_output(['git','-C',str(SRC),*a]).decode().strip()
b=read(R/'input-before.json');assert git('rev-parse','HEAD')==b['commit'] and not git('status','--porcelain')
for f in b['author_manifest']['files']:assert sha(E/f['file'])==f['sha256']
for f in b['snapshot_files']:assert sha(S/f['path'])==f['sha256']
baseline=(R/'baseline-runtime_coding_windows.go').read_bytes();production=(SRC/'internal/host/runtime_coding_windows.go').read_bytes()
assert production==baseline.replace(b'builtins := map[string]bool{',b'builtins := map[string]bool{"any": true, ',1),'unexpected production delta'
assert sha(SRC/'internal/host/runtime_coding_windows.go')==b['author_report']['source_sha256']
assert sha(SRC/'internal/host/runtime_coding_windows_test.go')==b['author_report']['test_sha256']
actual=pathlib.Path(b['actual_workspace'])
for f in b['actual326_files']:
 assert sha(actual/f['path'])==f['sha256'] and sha(R/'actual326-fixture'/f['path'])==f['sha256']
for parent,names in b['production_directory_members'].items():assert sorted(p.name for p in (actual/parent).glob('*.go') if not p.name.endswith('_test.go'))==names
assert sha(R/'scope-input.json')==b['author_report']['original_scope_input_sha256']
results={n:read(R/'runs'/f'{n}.json') for n in ['baseline','candidate']}
assert all(r['exit']==0 for r in results.values())
for n in results:
 raw=(R/'runs'/f'{n}.stdout.txt').read_text(encoding='utf8');assert '\nPASS\n' in raw and '--- SKIP' not in raw and '--- FAIL' not in raw
assert not list((R/'fixture-temp').iterdir())
report={'schema':'researchos.coding-any-independent-review/1','at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'reviewer':'codex:/root/attach_review_resume','verdict':'APPROVE_EXACT2_SOURCE_CHECKER_SCOPE_ONLY','findings':[],
 'source':{'worktree':str(SRC),'commit':b['commit'],'tree':b['tree'],'base':b['base'],'paths':b['author_report']['changed_paths'],'production_sha256':sha(SRC/'internal/host/runtime_coding_windows.go'),'tests_sha256':sha(SRC/'internal/host/runtime_coding_windows_test.go'),'author_manifest_sha256':sha(E/'manifest.sha256.json'),'author_report_sha256':sha(E/'repair-report.json'),'clean_before_after':True,'production_delta':'Exactly one insertion: any:true in existing predeclared builtin/type map. All other production bytes identical to base.'},
 'evidence':{'snapshot_original_files_verified_before_after':len(b['snapshot_files']),'author_manifest_members_verified_before_after':len(b['author_manifest']['files']),'original_workspace':str(actual),'actual_scope_sha256':sha(R/'scope-input.json'),'original_scope_audit_sha256':b['author_report']['original_326_file_audit_sha256'],'original_source_files_before_after':326,'isolated_fixture_files_hash_identical':326,'production_package_directory_members_before_after_unchanged':True,'pinned_go_sha256':b['go_exe_sha256'],'baseline_production_source_sha256':sha(R/'baseline-runtime_coding_windows.go'),'baseline_overlay_sha256':sha(R/'baseline-overlay.json'),'candidate_production_checker_call':'same-package reviewer test directly calls validateCodingCheckSources compiled from immutable source snapshot; no extracted or reimplemented checker','baseline_production_checker_call':'Native Go overlay maps only runtime_coding_windows.go to exact base blob; same direct function call and identical fixture','test_results':results},
 'validation':{'baseline':'2 top-level tests with 6 subcases, exit0, no skip. Original326 and two legal any conversions reproduce exact missing-any rejection. Guard negatives remain refusals.','candidate':'4 top-level tests with 21 subcases, exit0, no skip. Original326 accepted; 15 product inventory cases, 6 independent any/helper cases, private frame tests pass.','independent_positive_cases':['any(nil) in production returns nil','nested any(any(nil)) in test compares to nil'],'independent_negative_cases':['missingHelper with any(nil) in test','missingHelper with any(nil) in production','unselected same-package test helper file remains unavailable','dot-import helper authority remains unavailable'],'product_gates_retested':['missing go.mod and go.sum','omitted production source','missing helper with and without any conversion','import closure and embeds','anchored selector and nonzero tests','TestMain/init rejection','private frame action mixing, traversal, limits and duplicate keys']},
 'scope_statement':{'read_paths_retained':326,'write_paths_retained':2,'scope_expanded':False,'scope_files_written':False,'real_authorized_workspace_written':False,'read_write_or_tool_native_budget_policy_code_changed':False,'explanation':'Only recognizing the Go predeclared alias any as a legal call-shaped type conversion changes. Source inventory, import/embed closure, helper denial and all read/write authorization remain intact. Original326 hashes and production membership are unchanged before/after; no additional source authorization was supplied.'},
 'limitations':['Inventory checker is not the final semantic/compiler/native check; acceptance of a source inventory does not claim its tests execute successfully. Author positive fixture reused Value()!=1 with nil-returning Value; the checker test is valid for its inventory purpose only. Reviewer positive fixtures use nil comparisons.','The first live Desktop PREPARE error text was not recovered; this proves deterministic production checker repair only.','Root integration and new Core/verifier/validator plus source-bound package build remain required. Old installed Core/package cannot substantiate the repaired behavior.','Fresh actual GUI PREPARE and any later qualification gates remain unverified by this source review.'],
 'boundaries':{'Main_writes':False,'author_source_writes':False,'original_workspace_writes':False,'Canon_writes':False,'real_DB_access':False,'GUI_CDP_API_calls':False,'provider_model_calls':0,'installed_package_writes':False,'formal_increment':0,'formal_cases':'0/42','all_22_parent_tasks':'OPEN','reviewer_test_failures':0,'author_initial_replay_failure':'Preserved in frozen author evidence; not erased or reclassified.'},'cleanup':{'fixture_temp_empty':True,'retained_snapshots':'Source and326 fixture retained as reproducible evidence; no disposable runtime temp files remain.'}}
save('FINAL-report.json',report)
members=[{'path':p.relative_to(R).as_posix(),'sha256':sha(p),'bytes':p.stat().st_size} for p in sorted(R.rglob('*')) if p.is_file() and p.name!='FINAL-manifest.json']
save('FINAL-manifest.json',{'schema':'researchos.coding-any-independent-review-manifest/1','report_sha256':sha(R/'FINAL-report.json'),'members':members})
print(json.dumps({'report_sha256':sha(R/'FINAL-report.json'),'manifest_sha256':sha(R/'FINAL-manifest.json'),'members':len(members),'verdict':report['verdict']}))
